namespace ledwall {
namespace {
constexpr float MAX_COORDINATE = 100000.0f;
constexpr float PI = 3.14159265358979323846f;

struct PreparedEffect {
  const EffectConfig* config;
  float dx, dy, phase;
};

// Prepare time and direction once for an entire frame, rather than per LED.
PreparedEffect prepareEffect(const EffectConfig& effect, uint64_t timeMs) {
  float radians = effect.direction * (PI / 180.0f);
#ifdef ARDUINO_ARCH_ESP32
  float dx = cos_approx(radians), dy = sin_approx(radians);
#else
  float dx = float(std::cos(radians)), dy = float(std::sin(radians));
#endif
  return {&effect, dx, dy,
    float(std::fmod(double(timeMs) * double(effect.speed) / 1000.0, 1.0))};
}

float wrapPhase(float value) { return value - std::floor(value); }
float triangle(float phase) { return 1.0f - std::fabs(2.0f * wrapPhase(phase) - 1.0f); }

// Convert a cyclic hue into RGB with integer interpolation and full saturation.
Color rainbow(float phase) {
  unsigned hue = unsigned(wrapPhase(phase) * 1536.0f);
  unsigned region = hue >> 8;
  uint8_t rise = hue & 255, fall = 255 - rise;
  switch (region) {
    case 0: return {255, rise, 0};
    case 1: return {fall, 255, 0};
    case 2: return {0, 255, rise};
    case 3: return {0, fall, 255};
    case 4: return {rise, 0, 255};
    default: return {255, 0, fall};
  }
}

// A stateless integer hash makes spatial sparkle reproducible across controllers.
uint32_t hashValue(uint32_t value) {
  value ^= value >> 16;
  value *= 0x7feb352dU;
  value ^= value >> 15;
  value *= 0x846ca68bU;
  return value ^ (value >> 16);
}

// All effects sample the same coordinate/time field without neighbouring-pixel state.
Color samplePrepared(const PreparedEffect& prepared, float x, float y) {
  const EffectConfig& effect = *prepared.config;
  float projection = (x * prepared.dx + y * prepared.dy) / effect.wavelength;
  if (effect.type == EffectType::Rainbow) return rainbow(projection + prepared.phase);
  if (effect.type == EffectType::Wave) {
    uint8_t value = uint8_t(255.0f * triangle(projection - prepared.phase));
    return {uint8_t(value / 8), uint8_t(value / 2), value};
  }
  if (effect.type == EffectType::Ripple) {
    float dx = x - effect.centerX, dy = y - effect.centerY;
    uint8_t value = uint8_t(255.0f * triangle(std::sqrt(dx * dx + dy * dy) / effect.wavelength - prepared.phase));
    return {uint8_t(value / 4), value, value};
  }
  // Hash a coarse spatial grid, then move a smooth threshold through each cell.
  uint32_t cellX = uint32_t(x / effect.wavelength);
  uint32_t cellY = uint32_t(y / effect.wavelength);
  uint32_t hash = hashValue(cellX ^ hashValue(cellY + effect.seed));
  float pulse = triangle(prepared.phase + float(hash & 65535) / 65536.0f);
  uint8_t value = pulse > 0.8f ? uint8_t((pulse - 0.8f) * 1275.0f) : 0;
  return {value, uint8_t(value * 3U / 4U), uint8_t(value / 3)};
}

bool validCoordinate(float value, float limit) { return std::isfinite(value) && value >= 0.0f && value <= limit; }

bool validIp(const uint8_t* ip) { return ip[0] > 0 && ip[0] < 224 && ip[0] != 127; }
} // namespace

Config defaultConfig() {
  return Config();
}

bool validateConfig(const Config& config, const char*& error) {
  error = nullptr;
  if (config.version != CONFIG_VERSION) { error = "Unsupported configuration version"; return false; }
  if (!std::isfinite(config.canvas.width) || !std::isfinite(config.canvas.height) || config.canvas.width <= 0.0f || config.canvas.height <= 0.0f || config.canvas.width > MAX_COORDINATE || config.canvas.height > MAX_COORDINATE) {
    error = "Canvas dimensions must be positive and at most 100000"; return false;
  }
  if (config.fps < 1 || config.fps > 60) { error = "FPS must be between 1 and 60"; return false; }
  const EffectConfig& effect = config.effect;
  if (!effectName(effect.type) || !std::isfinite(effect.speed) || std::fabs(effect.speed) > 10.0f || !std::isfinite(effect.wavelength) || effect.wavelength < 0.01f || effect.wavelength > MAX_COORDINATE || !std::isfinite(effect.direction) || std::fabs(effect.direction) > 360.0f || !validCoordinate(effect.centerX, config.canvas.width) || !validCoordinate(effect.centerY, config.canvas.height)) {
    error = "Invalid effect parameters"; return false;
  }
  if (config.controllerCount > MAX_CONTROLLERS || config.stripCount > MAX_STRIPS) { error = "Controller or strip capacity exceeded"; return false; }
  if (config.enabled && (!config.controllerCount || !config.stripCount)) { error = "Enabled layout requires controllers and strips"; return false; }
  size_t totalLeds = 0;
  for (size_t i = 0; i < config.controllerCount; i++) {
    const Controller& controller = config.controllers[i];
    if (!controller.id || !controller.leds || !validIp(controller.ip)) { error = "Invalid controller ID, LED count or unicast IPv4 address"; return false; }
    totalLeds += controller.leds;
    if (totalLeds > MAX_OUTPUT_LEDS) { error = "Total controller LED capacity exceeds 4096"; return false; }
    for (size_t j = 0; j < i; j++) {
      if (controller.id == config.controllers[j].id || std::memcmp(controller.ip, config.controllers[j].ip, 4) == 0) { error = "Duplicate controller ID or address"; return false; }
    }
  }
  for (size_t i = 0; i < config.stripCount; i++) {
    const Strip& strip = config.strips[i];
    if (!strip.id || !strip.count || !validCoordinate(strip.x1, config.canvas.width) || !validCoordinate(strip.x2, config.canvas.width) || !validCoordinate(strip.y1, config.canvas.height) || !validCoordinate(strip.y2, config.canvas.height)) { error = "Invalid strip ID, count or endpoints"; return false; }
    size_t controllerIndex = 0;
    while (controllerIndex < config.controllerCount && config.controllers[controllerIndex].id != strip.controller) controllerIndex++;
    if (controllerIndex == config.controllerCount || uint32_t(strip.start) + strip.count > config.controllers[controllerIndex].leds) { error = "Strip references an unknown controller or exceeds its LED capacity"; return false; }
    for (size_t j = 0; j < i; j++) {
      const Strip& other = config.strips[j];
      if (strip.id == other.id) { error = "Duplicate strip ID"; return false; }
      if (strip.controller == other.controller && strip.start < uint32_t(other.start) + other.count && other.start < uint32_t(strip.start) + strip.count) { error = "Physical LED intervals overlap"; return false; }
    }
  }
  return true;
}

const char* effectName(EffectType type) {
  switch (type) {
    case EffectType::Rainbow: return "rainbow";
    case EffectType::Wave: return "wave";
    case EffectType::Ripple: return "ripple";
    case EffectType::Noise: return "noise";
    default: return nullptr;
  }
}

bool parseEffectName(const char* name, EffectType& type) {
  if (!name) return false;
  for (unsigned i = 0; i < 4; i++) {
    EffectType candidate = EffectType(i);
    if (std::strncmp(name, effectName(candidate), 8) == 0) { type = candidate; return true; }
  }
  return false;
}

size_t frameBytes(const Config& config) {
  if (config.controllerCount > MAX_CONTROLLERS) return 0;
  size_t leds = 0;
  for (size_t i = 0; i < config.controllerCount; i++) leds += config.controllers[i].leds;
  return leds <= MAX_OUTPUT_LEDS ? leds * 3 : 0;
}

size_t controllerOffset(const Config& config, size_t controllerIndex) {
  if (config.controllerCount > MAX_CONTROLLERS || controllerIndex > config.controllerCount) return SIZE_MAX;
  size_t offset = 0;
  for (size_t i = 0; i < controllerIndex; i++) offset += size_t(config.controllers[i].leds) * 3;
  return offset;
}

bool ledPosition(const Strip& strip, size_t physicalIndex, float& x, float& y) {
  if (physicalIndex >= strip.count) return false;
  size_t geometricIndex = strip.reverse ? strip.count - 1 - physicalIndex : physicalIndex;
  float fraction = strip.count > 1 ? float(geometricIndex) / float(strip.count - 1) : 0.0f;
  x = strip.x1 + (strip.x2 - strip.x1) * fraction;
  y = strip.y1 + (strip.y2 - strip.y1) * fraction;
  return true;
}

Color sampleEffect(const EffectConfig& effect, float x, float y, uint64_t timeMs) {
  if (!validCoordinate(x, MAX_COORDINATE) || !validCoordinate(y, MAX_COORDINATE) || !effectName(effect.type) || !std::isfinite(effect.wavelength) || effect.wavelength < 0.01f || effect.wavelength > MAX_COORDINATE || !std::isfinite(effect.direction) || std::fabs(effect.direction) > 360.0f || !std::isfinite(effect.speed) || std::fabs(effect.speed) > 10.0f || !validCoordinate(effect.centerX, MAX_COORDINATE) || !validCoordinate(effect.centerY, MAX_COORDINATE)) return {0, 0, 0};
  return samplePrepared(prepareEffect(effect, timeMs), x, y);
}

bool renderFrame(const Config& config, uint64_t timeMs, uint8_t* output, size_t capacity) {
  const char* error;
  if (!validateConfig(config, error)) return false;
  size_t bytes = frameBytes(config);
  if (capacity < bytes || (bytes && !output)) return false;
  if (!bytes) return true;
  std::memset(output, 0, bytes);
  PreparedEffect prepared = prepareEffect(config.effect, timeMs);
  for (size_t i = 0; i < config.stripCount; i++) {
    const Strip& strip = config.strips[i];
    size_t controllerIndex = 0;
    while (config.controllers[controllerIndex].id != strip.controller) controllerIndex++;
    size_t offset = controllerOffset(config, controllerIndex) + size_t(strip.start) * 3;
    float reciprocal = strip.count > 1 ? 1.0f / float(strip.count - 1) : 0.0f;
    float stepX = (strip.x2 - strip.x1) * reciprocal, stepY = (strip.y2 - strip.y1) * reciprocal;
    // Multiplication by each index avoids accumulated floating-point drift on long strips.
    for (size_t physical = 0; physical < strip.count; physical++) {
      size_t geometric = strip.reverse ? strip.count - 1 - physical : physical;
      Color color = samplePrepared(prepared, strip.x1 + stepX * geometric, strip.y1 + stepY * geometric);
      output[offset++] = color.r;
      output[offset++] = color.g;
      output[offset++] = color.b;
    }
  }
  return true;
}

} // namespace ledwall
